(function(){'use strict';
const C=window.DeskCore,D=window.DeskData,S=window.DeskStorage,M=window.DeskModules,RAW=window.DESK_SEED,PREF='xuji.headhunter.preferences.v2';
let MODE='work',KEY='xuji.headhunter.work.v1',LOCK='xuji-headhunter-work',store;
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name)=>{const paths={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',check:'<path d="m5 12 4 4L19 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',brief:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V4h8v3M3 12h18M10 12v3h4v-3"/>',change:'<path d="M4 7h15l-4-4M20 17H5l4 4M20 7v5M4 17v-5"/>',shield:'<path d="M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6z"/><path d="m8 12 3 3 5-6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',plus:'<path d="M12 4v16M4 12h16"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',wait:'<path d="M6 3h12M6 21h12M7 3v5l10 8v5M17 3v5L7 16v5"/>',doc:'<path d="M6 3h8l4 4v14H6zM14 3v5h4M9 12h6M9 16h6"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>'};return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+(paths[name]||paths.doc)+'</svg>';};
let state,stateTrusted=false,storageOK=true,storageError='',prefs={actor:'',asof:C.localToday(),clockMode:'live',nav:'followups',filter:'active',owner:'all',job:'all',query:'',showClosed:false},formContext=null,returnFocus=null,toastTimer,dirty=false,saving=false;
let savedPrefs={};try{savedPrefs=D.preferences(localStorage.getItem(PREF));}catch{}
if(savedPrefs.mode==='demo')MODE='demo';
function fresh(){return MODE==='demo'?D.validate(C.seed(RAW)):D.emptyWorkspace('local-owner','local-workspace','我');}
function connectStore(){KEY=MODE==='demo'?'xuji.headhunter.demo.v1':'xuji.headhunter.work.v1';LOCK='xuji-headhunter-'+MODE;store=S.create({getItem:k=>window.localStorage.getItem(k),setItem:(k,v)=>window.localStorage.setItem(k,v)},KEY);}
function read(){return store.read()||fresh();}
function loadWorkspace(){
 connectStore();storageOK=true;storageError='';
 try{state=read();if(store.raw()===null)state=store.write(state,null);stateTrusted=true;}catch(e){state=fresh();stateTrusted=false;storageOK=false;storageError=e.message;}
 prefs.actor=state.users.some(u=>u.id===savedPrefs.actor)?savedPrefs.actor:state.users[0].id;
 prefs.clockMode=MODE==='work'?'live':'fixed';prefs.asof=MODE==='work'?C.localToday():'2026-10-19';
 if(savedPrefs.mode===MODE&&savedPrefs.clockMode==='fixed'&&C.validDate(savedPrefs.asof)){prefs.asof=savedPrefs.asof;prefs.clockMode='fixed';}
}
loadWorkspace();
function savePrefs(){try{savedPrefs={actor:prefs.actor,asof:prefs.asof,clockMode:prefs.clockMode,mode:MODE};localStorage.setItem(PREF,JSON.stringify(savedPrefs));}catch{toast('显示偏好未能保存；业务数据请以保存结果为准',true);}}
function toast(t,bad=false){clearTimeout(toastTimer);$('#toast').innerHTML='<div class="toast '+(bad?'error':'')+'" role="status">'+esc(t)+'</div>';toastTimer=setTimeout(()=>$('#toast').innerHTML='',4200);}
async function withWrite(run){if(!storageOK)throw Error(storageError||'当前存储不可用，请先到数据管理恢复');return navigator.locks?navigator.locks.request(LOCK,run):run();}
async function mutate(op){const target=store,mode=MODE,actor=prefs.actor,tenant=state.tenant_id;return withWrite(()=>{if(MODE!==mode)throw Error("工作区已切换，请重新操作");const old=target.raw();if(old===null){storageOK=false;storageError='本地数据已被清除，已停止写入；请先下载页面保留副本，再恢复备份或重新打开';render();throw Error(storageError);}const latest=target.read(),result=C.apply(latest,{tenant_id:tenant,...op},actor,new Date().toISOString());state=target.write(result.state,old);stateTrusted=true;return result;});}
const id=()=>globalThis.crypto?.randomUUID?crypto.randomUUID():'local-'+Date.now()+'-'+Math.random().toString(16).slice(2);
function jobFor(c){return state.jobs.find(j=>j.id===c.job_id)||{title:'未知职位',client_alias:'',status:'closed'};}
function userName(uid){return state.users.find(u=>u.id===uid)?.alias||'未分配';}
function currentRows(){return state.commitments.filter(c=>(prefs.owner==='all'||c.assigned_to===prefs.owner)&&(prefs.job==='all'||c.job_id===prefs.job)&&(!prefs.query||(c.action_text+' '+(c.person_alias||'')+' '+jobFor(c).title+' '+jobFor(c).client_alias+' '+(c.condition_note||'')+' '+C.commitmentNotes(state,c.id).map(n=>n.note).join(' ')).toLowerCase().includes(prefs.query.toLowerCase())));}
function filteredRows(){return currentRows().filter(c=>prefs.filter==='active'?c.status==='pending':prefs.filter==='reminders'?c.status==='pending'&&!!c.reminder_on&&c.reminder_on<=prefs.asof:C.view(c,prefs.asof)===prefs.filter).sort((a,b)=>{let rank={overdue:0,due_today:1,waiting_condition:2,undated:3,upcoming:4,done:5,cancelled:6,rescheduled:7};return rank[C.view(a,prefs.asof)]-rank[C.view(b,prefs.asof)]||(a.due_date||'9999').localeCompare(b.due_date||'9999');});}
const viewLabels={overdue:'已逾期',due_today:'今日到期',upcoming:'未到期',undated:'未定日期',waiting_condition:'等待条件',done:'已完成',cancelled:'已取消',rescheduled:'改期历史'};
function viewTag(c){let v=C.view(c,prefs.asof),color=v==='overdue'?'red':v==='due_today'?'green':v==='waiting_condition'?'amber':'neutral';return '<span class="tag '+color+'">'+viewLabels[v]+'</span>';}
function reminderTag(c){return c.status==='pending'&&c.reminder_on?'<span class="tag '+(c.reminder_on<=prefs.asof?'amber':'neutral')+'">内部回看 '+esc(c.reminder_on)+(c.reminder_on<=prefs.asof?' · 已到日':'')+'</span>':'';}
function taskItem(c){let j=jobFor(c),can=C.canEdit(state,c,prefs.actor),v=C.view(c,prefs.asof);let button=c.status==='pending'?(c.condition_state==='waiting'?'核实条件':!c.due_confirmed?'确认日期':'标记完成'):'查看记录';let action=c.status==='pending'&&can?(c.condition_state==='waiting'?'release':!c.due_confirmed?'confirm_date':'complete'):'detail';return '<article class="item"><div class="item-main"><div class="item-top">'+viewTag(c)+reminderTag(c)+'<span class="person">'+esc(c.person_alias||'内部待办')+'</span>'+(j.status==='closed'?'<span class="tag job-closed-badge">职位已关闭</span>':'')+'</div><p class="item-title" role="button" tabindex="0" data-action="detail" data-id="'+esc(c.id)+'">'+esc(c.action_text)+'</p>'+(c.condition_state==='waiting'?'<div class="note-block" style="margin:4px 0 9px;padding:8px 11px">等待什么：'+esc(c.condition_note)+'</div>':'')+'<div class="meta"><button class="joblink" data-action="job" data-id="'+esc(c.job_id)+'">'+esc(j.title)+'</button><span class="faint-divider">·</span><span>'+esc(userName(c.assigned_to))+'</span>'+(c.rescheduled_from?'<span class="tag">已改期</span>':'')+'</div></div><div class="item-end"><span class="deadline '+(v==='overdue'?'overdue':'')+'">'+(c.due_confirmed&&c.due_date?esc(c.due_date.slice(5).replace('-',' / ')):(v==='waiting_condition'?'等待触发':'尚无期限'))+'</span><button class="tiny-action '+(!can?'muted':'')+'" data-action="'+action+'" data-id="'+esc(c.id)+'">'+(!can?'查看':button)+'</button></div></article>';}
function changeItem(c){let j=jobFor(c);const labels={unknown:'同步待确认',not_started:'尚未同步',some_synced:'已向至少一位同步',not_applicable:'无需同步'};return '<article class="item"><div class="item-main"><div class="item-top"><span class="tag '+(c.status==='active'?'green':'neutral')+'">'+(c.status==='active'?'有效记录':c.status==='void'?'已作废':'已被替代')+'</span><span class="person">'+esc(c.happened_on)+'</span></div><p class="item-title" tabindex="0" role="button" data-action="change_detail" data-id="'+c.id+'">'+esc(c.description)+'</p><div class="meta"><button class="joblink" data-action="job" data-id="'+c.job_id+'">'+esc(j.title)+'</button><span>·</span><span>'+labels[c.sync_status]+'</span></div></div><button class="row-more" aria-label="查看变更详情" data-action="change_detail" data-id="'+c.id+'">···</button></article>';}
function searchBar(jobFilter=true){return '<div class="filterbar"><label class="search">'+icon('search')+'<input id="search-input" type="search" value="'+esc(prefs.query)+'" placeholder="搜索事项、人物或职位…" aria-label="搜索事项"></label><select class="compact-select" id="owner-filter" aria-label="跟进负责人"><option value="all">全部跟进负责人</option>'+state.users.map(u=>'<option value="'+u.id+'" '+(prefs.owner===u.id?'selected':'')+'>'+esc(u.alias)+'</option>').join('')+'</select>'+(jobFilter?'<select class="compact-select" id="job-filter" aria-label="筛选职位"><option value="all">全部职位（含已关闭）</option>'+state.jobs.map(j=>'<option value="'+j.id+'" '+(prefs.job===j.id?'selected':'')+'>'+esc(j.title)+(j.status==='closed'?' · 已关闭':'')+'</option>').join('')+'</select>':'')+'</div>';}
function followups(){let rows=currentRows(),p=C.partitions({...state,commitments:rows},prefs.asof),stats=[['overdue','需要核实的逾期事项','尚未记录完成，请核实','red','clock'],['due_today','今天需要跟进','截止日当天，及时确认','green','check'],['waiting_condition','等待条件满足','条件未满足，不判定逾期','amber','wait'],['undated','尚未确认期限','明确承诺也可能没有日期','','doc']];return '<div class="cards">'+stats.map(([v,label,note,color,ic])=>'<button class="metric '+color+'" data-action="filter" data-value="'+v+'"><div class="metric-top">'+label+'<span class="metric-icon">'+icon(ic)+'</span></div><strong>'+p[v].length.toString().padStart(2,'0')+'</strong><small>'+note+'</small></button>').join('')+'</div>'+searchBar()+'<div class="layout"><section class="panel"><div class="panel-head"><h2>跟进清单 <span class="kbd">/ '+filteredRows().length+' 项</span></h2><small>先看记录，再做下一步</small></div><div class="filters">'+[['active','待跟进'],['reminders','该回看了'],['overdue','逾期'],['due_today','今天'],['upcoming','未到期'],['waiting_condition','等待条件'],['undated','未定日期']].map(([v,t])=>'<button class="tab '+(prefs.filter===v?'active':'')+'" data-action="filter" data-value="'+v+'">'+t+'</button>').join('')+'</div>'+listOrEmpty(filteredRows(),taskItem,'当前筛选下没有待办','试试切换筛选，或记录一项新的承诺。')+'</section>'+rightColumn()+'</div>';}
function listOrEmpty(rows,renderer,title,sub){return rows.length?rows.map(renderer).join(''):'<div class="empty"><strong>'+title+'</strong>'+sub+'</div>';}
function rightColumn(){let due=C.reminders(state,prefs.asof).length;let changes=state.changes.filter(c=>c.status==='active'&&(prefs.job==='all'||c.job_id===prefs.job)).sort((a,b)=>b.happened_on.localeCompare(a.happened_on)).slice(0,3);return '<aside class="right-column"><section class="aside-card highlight"><h3>内部回看日已到 · '+due+' 项</h3><p class="small">这是你安排的回看日，不代表对方承诺到期。页面关闭后不会主动通知。</p><button class="button-link" data-action="reminder_list">查看提醒清单 →</button></section><section class="aside-card"><h3>最近的需求变化</h3>'+changes.map(c=>'<div class="change-preview"><strong><button class="button-link" data-action="job" data-id="'+c.job_id+'">'+esc(jobFor(c).title)+'</button></strong><p>'+esc(c.description)+'</p></div>').join('')+'<button class="button-link" data-action="nav" data-value="changes" style="margin-top:8px">查看全部变化 →</button></section><section class="aside-card highlight"><h3>下一次联系前，先回看</h3><p class="small">对方上次答应了什么？<br>这个职位最近变了什么？<br>还有哪个条件需要核实？</p><button class="button-link" data-action="nav" data-value="jobs">进入职位看板 →</button></section><p class="footnote">这里记录已知的变化与承诺。未被告知或录入的信息，不会被自动发现。</p></aside>';}
function jobGrid(){let rows=state.jobs.filter(j=>(prefs.showClosed||j.status!=='closed')&&(!prefs.query||(j.title+j.client_alias).includes(prefs.query)));return '<button class="btn primary" data-action="new_job" style="margin-bottom:16px">＋ 新建职位</button><div class="filterbar"><label class="search">'+icon('search')+'<input id="search-input" value="'+esc(prefs.query)+'" placeholder="搜索职位或客户别名…" aria-label="搜索职位"></label><label class="check-line" style="margin:0"><input id="show-closed" type="checkbox" '+(prefs.showClosed?'checked':'')+'>包含已关闭职位</label></div><div class="job-grid">'+rows.map(j=>{let cs=state.commitments.filter(c=>c.job_id===j.id&&c.status==='pending'),over=cs.filter(c=>C.view(c,prefs.asof)==='overdue').length;return '<button class="job-card" data-action="job" data-id="'+j.id+'"><span class="tag '+(j.status==='open'?'green':'neutral')+'">'+(j.status==='open'?'推进中':'已关闭')+'</span><h3>'+esc(j.title)+'</h3><p>'+esc(j.client_alias)+' · '+esc(userName(j.owner_id))+'</p><div class="stats"><span>'+cs.length+' 项待跟进</span><span style="color:'+(over?'#b36b59':'#98a68c')+'">'+(over?over+' 项逾期':'查看职位 →')+'</span></div></button>';}).join('')+'</div>'+(rows.length?'':'<div class="empty">没有找到职位</div>');}
function jobDetail(){let j=state.jobs.find(x=>x.id===prefs.jobDetail);if(!j){prefs.nav='jobs';return jobGrid();}let rows=state.commitments.filter(c=>c.job_id===j.id&&c.status==='pending'),changes=state.changes.filter(c=>c.job_id===j.id).sort((a,b)=>b.happened_on.localeCompare(a.happened_on));return '<div class="job-detail-head"><button class="btn ghost" data-action="nav" data-value="jobs">← 返回职位</button><span class="tag '+(j.status==='closed'?'neutral':'green')+'">'+(j.status==='closed'?'职位已关闭':'推进中')+'</span><span class="person">'+esc(j.client_alias)+' · '+esc(userName(j.owner_id))+'</span>'+(j.owner_id===prefs.actor?'<button class="button-link" data-action="edit_job" data-id="'+j.id+'">修改职位</button><button class="button-link" style="margin-left:auto" data-action="job_toggle" data-id="'+j.id+'">'+(j.status==='closed'?'重新打开职位':'关闭职位')+'</button>':'')+'</div>'+(j.status==='closed'?'<div class="notice">该职位已关闭。未完成事项仍保留，由顾问逐条核实、完成或取消；不会自动批量关闭。清理检查日：'+esc(j.cleanup_due_on||'待定')+'。</div>':'')+'<div class="two-col"><section class="panel"><div class="panel-head"><h2>待跟进事项 <span class="kbd">/ '+rows.length+'</span></h2><button class="link" data-action="new_commitment" data-job="'+j.id+'">＋ 记录承诺</button></div>'+listOrEmpty(rows,taskItem,'暂无待跟进事项','可以记录承诺或内部核实事项。')+'</section><section class="panel"><div class="panel-head"><h2>已记录的需求变化</h2><button class="link" data-action="new_change" data-job="'+j.id+'">＋ 记录变化</button></div><p class="history-note">变化不会自动取消承诺。这里是变更日志，不代表完整最新 JD。</p>'+listOrEmpty(changes,changeItem,'暂无变化记录','新获知的变化可以记录在这里。')+'</section></div>';}
function changesPage(){let rows=state.changes.filter(c=>(prefs.job==='all'||c.job_id===prefs.job)&&(prefs.owner==='all'||c.created_by===prefs.owner)&&(!prefs.query||(c.description+jobFor(c).title).includes(prefs.query))).sort((a,b)=>b.happened_on.localeCompare(a.happened_on));return searchBar()+'<div class="layout"><section class="panel"><div class="panel-head"><h2>已记录的需求变化 <span class="kbd">/ '+rows.length+'</span></h2><small>保留来源，不自动解释影响</small></div>'+listOrEmpty(rows,changeItem,'没有符合条件的记录','试试其他关键词。')+'</section>'+rightColumn()+'</div>';}
function history(){let rows=currentRows().filter(c=>c.status!=='pending');return searchBar()+'<section class="panel"><div class="panel-head"><h2>完成与改期历史</h2><small>'+rows.length+' 条记录</small></div><p class="history-note">改期旧条目不计入活跃数；新条目保留为当前承诺。完成、取消、改期分别记录。</p>'+listOrEmpty(rows,taskItem,'暂无历史记录','完成或改期后会显示在这里。')+'</section>';}
function checks(){let structural=true;try{D.validate(state);}catch{structural=false;}let p=C.partitions(state,prefs.asof),all=Object.values(p).flat().map(x=>x.id),unique=new Set(all);let children=state.commitments.map(c=>c.rescheduled_from).filter(Boolean),validJobs=state.commitments.every(c=>jobFor(c).title!=='未知职位'&&c.tenant_id===state.tenant_id);return [['数据结构、归属与改期链完整',structural],['记录分组互斥且完整',all.length===state.commitments.length&&unique.size===all.length],['来源职位与工作区一致',validJobs],['等待条件没有确认截止日',state.commitments.filter(c=>c.condition_state==='waiting').every(c=>!c.due_date&&!c.due_confirmed&&c.condition_note)],['每个旧承诺最多一个改期后继',new Set(children).size===children.length],['确认日期均合法',state.commitments.every(c=>!c.due_confirmed||C.validDate(c.due_date))]];}
function validation(){let p=C.partitions(state,prefs.asof);return '<div class="two-col"><section class="panel"><div class="panel-head"><h2>当前数据检查</h2><small>浏览器规则检查 · 非真实需求验证</small></div>'+checks().map(([t,ok])=>'<div class="test-row"><span>'+t+'</span><span class="'+(ok?'status-pass':'tag red')+'">'+(ok?'通过':'需检查')+'</span></div>').join('')+'<div class="doc"><p>当前共 '+state.commitments.length+' 条承诺记录，'+state.commitments.filter(c=>c.status==='pending').length+' 条待跟进。已关闭职位上的未完成事项是交叉标签，包含在分组里，不重复累加。</p><div class="about-actions"><button class="btn secondary" data-action="export_report">导出检查结果</button><button class="btn ghost" data-action="show_formats">查看复杂文本样例</button></div></div></section><section class="panel"><div class="panel-head"><h2>分组结果</h2><small>'+esc(prefs.asof)+'</small></div>'+C.VIEWS.map(v=>'<div class="test-row"><span>'+viewLabels[v]+'</span><span>'+p[v].length+' 条</span></div>').join('')+'</section></div>';
}
function about(){return '<section class="panel"><div class="doc"><h3>个人工作台 · 0.7.0</h3><p>工作区从空白职位开始，演示区保留合成样例；两个区的数据分开保存。请用客户与人员别名，只记录必要的事项、来源和日期。</p><h3>可靠保存与恢复</h3><p>只有写入成功后才提示已保存。每次修改前保留上一次状态，可在数据管理恢复；完整 JSON 备份带 SHA-256 校验，支持预览后恢复。文本导出只供阅读，不能替代完整备份。</p><h3>日期与人工确认</h3><p>默认按上海时区的今天判断到期，打开页面和跨日时更新。手选评估日会明确显示为历史/模拟日期；日期草稿永远要人工确认。等待条件未解除时不判逾期。</p><h3>以后怎么增加功能</h3><p>扩展模块通过独立入口注册，目前提供“联系前回看”、“内部回看提醒”和“跟进结果回看”，可在扩展工具中切换。后续功能应先确定字段、操作权限、数据迁移与验收用例，再加入；现有数据不会因未安装某个模块被删除。</p><h3>使用边界</h3><p>这是单人、本机、别名工作记录工具。身份切换不是登录，不提供企业鉴权或多人同步；未接入 CTS/Voice，不发送消息，不自动作出招聘决定。本地数据与备份未加密，请勿存简历、电话、邮箱或其他敏感资料。关闭页面后不会在后台主动通知。</p><p>浏览器清理数据、磁盘故障或更换访问地址都可能使记录无法找回；请定期下载完整备份，并保存在获准的位置。本次验证不代表能保证所有输入和环境永不出错。</p><button class="btn primary" data-action="nav" data-value="data">打开数据管理</button></div></section>';}
function dataPage(){let n=D.summary(state);return '<section class="panel"><div class="doc"><h3>备份与恢复</h3>'+(!storageOK&&stateTrusted?'<div class="notice">存储异常。页面仍保留最近读到的有效副本，可用完整备份按钮抢救；它可能不是其他页面修改后的最新版。</div>':'')+'<p>当前是'+(MODE==='work'?'个人工作区':'合成演示区')+'，'+n.jobs+' 个职位、'+n.commitments+' 条事项、'+n.changes+' 条变化、'+state.followups.length+' 条跟进结果。数据保存在当前浏览器，不会自动同步。</p><div class="about-actions"><button class="btn primary" data-action="backup">下载完整备份</button><button class="btn secondary" data-action="import_pick">选择备份并预览</button><button class="btn secondary" data-action="previous_preview">预览上一次保存</button><button class="btn ghost" data-action="export">导出阅读版文本</button></div><input type="file" id="backup-input" accept=".json,application/json" hidden><h3>恢复规则</h3><p>恢复会替换当前区的数据，不合并记录。备份校验和完整性检查通过后，仍须在预览中确认。演示备份不能恢复进工作区，工作备份也不能恢复进演示区。备份未加密，请妥善保管。</p><button class="btn ghost" data-action="raw_export">导出当前存储原文（排错用）</button><h3>工作区与演示区</h3><p>切换不会清空另一侧记录。演示区才提供恢复初始样例；工作区不会因“重置演示”而被清空。</p><button class="btn secondary" data-action="switch_mode">'+(MODE==='work'?'切换到合成演示区':'回到个人工作区')+'</button>'+(MODE==='demo'?'<button class="btn danger" data-action="reset">恢复初始模拟数据</button>':'')+'<h3>扩展模块</h3>'+M.list().map(m=>'<p><strong>'+esc(m.title)+'</strong>：'+esc(m.description)+'</p>').join('')+'<p class="footnote">修改前保留一个恢复点，不是无限历史版本。没有 Web Locks 的浏览器无法保证同时打开多个标签页写入的原子性，请只保留一个可编辑页面。</p></div></section>';}
function extensionsPage(){const available=M.list(),selected=available.some(x=>x.id===prefs.module)?prefs.module:available[0]?.id;let content;try{content=M.render(selected,{state,asof:prefs.asof,jobId:prefs.reviewJob,person:prefs.reviewPerson??null});}catch(e){content='<div class="notice">扩展暂不可用：'+esc(e.message)+'。核心记录功能不受影响。</div>';}return '<div class="filterbar"><label for="module-select">选择工具</label><select id="module-select" aria-label="选择扩展工具">'+available.map(m=>'<option value="'+esc(m.id)+'" '+(m.id===selected?'selected':'')+'>'+esc(m.title)+'</option>').join('')+'</select></div>'+content;}
function render(){if(prefs.clockMode==='live')prefs.asof=C.localToday();let focus=document.activeElement?.id,caret=document.activeElement?.selectionStart;let active=state.commitments.filter(c=>c.status==='pending').length;let titles={data:['DATA MANAGEMENT','数据有备份，工作有底。','下载完整备份、校验恢复；读取失败时保留原始内容。'],extensions:['CONTACT REVIEW','联系之前，把上下文找回来。','只回看已记录信息，不替你推断或发消息。'],followups:['TODAY’S FOLLOW-UPS','重生之我是猎头 MVP','这一世，需求记清楚，承诺跟到底。'],jobs:['POSITION WORKSPACE','先看清变化，再推进职位。','已记录的信息，按职位聚在一起。'],jobdetail:['POSITION WORKSPACE',state.jobs.find(j=>j.id===prefs.jobDetail)?.title||'职位详情','同一个职位的变化与承诺，在这里回看。'],changes:['REQUIREMENT CHANGES','需求在变，方向要跟上。','一句话保留变化与来源，交由顾问判断下一步。'],history:['WORK HISTORY','每次跟进，都留下来路。','完成、取消与改期分别保留。'],validation:['DEMO VALIDATION','让规则，经得起核对。','当前数据检查与预期状态，清楚展示。'],about:['ABOUT THIS DEMO','先跑通工作流，再验证价值。','合成数据、本地保存、无需外部模型。']}[prefs.nav]||['','',''];let count=state.jobs.filter(j=>j.status==='open').length;
$('#app').innerHTML='<div class="app"><aside class="side"><div class="brand"><span class="logo">↻</span><div><strong>重生之<br>我是猎头 <em>MVP</em></strong><small>THE NEXT CHAPTER</small></div></div><div class="nav-label">WORKSPACE / 工作台</div><nav class="nav" aria-label="工作台导航">'+[['followups','clock','我的跟进',active],['jobs','brief','职位看板',count],['changes','change','需求变化',null],['history','doc','跟进历史',null],['data','shield','数据管理',null],['extensions','doc','扩展工具',null],['validation','shield','数据检查',null],['about','info','使用说明',null]].map(([v,ic,t,n])=>'<button data-action="nav" data-value="'+v+'" class="'+((prefs.nav===v||(prefs.nav==='jobdetail'&&v==='jobs'))?'active':'')+'">'+icon(ic)+t+(n!==null?'<span class="nav-count">'+n+'</span>':'')+'</button>').join('')+'</nav><div class="side-bottom"><span class="local-dot"></span>本机浏览器保存<br>'+(MODE==='work'?'个人工作区 · 仅别名记录':'合成演示区')+'<br><button data-action="export">导出当前记录 ↗</button></div></aside><main class="main"><header class="top"><div class="breadcrumb">工作空间 <span>/ '+({followups:'我的跟进',jobs:'职位看板',jobdetail:'职位详情',changes:'需求变化',history:'跟进历史',validation:'数据检查',data:'数据管理',extensions:'扩展工具',about:'使用说明'}[prefs.nav]||'工作台')+'</span></div><div class="top-right"><span class="tag">'+(MODE==='work'?'本机负责人':'模拟身份')+'</span><div class="avatar">'+esc(MODE==='work'?'我':prefs.actor.slice(-2))+'</div><select class="actor" id="actor-select" aria-label="切换负责人">'+state.users.map(u=>'<option value="'+u.id+'" '+(u.id===prefs.actor?'selected':'')+'>'+esc(u.alias)+'</option>').join('')+'</select></div></header><div class="demo-strip"><span><span class="pill">'+(MODE==='work'?'个人工作区':'合成数据演示')+'</span> '+(MODE==='work'?'请使用别名，及时下载完整备份。':'所有人物与沟通均为虚构。')+' <button class="button-link" data-action="switch_mode">'+(MODE==='work'?'查看演示':'回到工作区')+'</button></span><div class="clock"><span>'+(prefs.clockMode==='live'?'今天 · 上海':'手选评估日')+'</span><input id="asof-date" type="date" aria-label="评估日期" value="'+esc(prefs.asof)+'"><button data-action="today">今天</button></div></div>'+(!storageOK?'<div class="persist-warning" role="alert">'+esc(storageError)+'<button data-action="nav" data-value="data">前往数据管理</button></div>':'')+'<section class="hero"><div><div class="eyebrow">'+titles[0]+'</div><h1>'+esc(titles[1])+'</h1><p>'+titles[2]+'</p></div><div class="hero-actions"><button class="btn secondary" data-action="new_change">'+icon('change')+'记一条变化</button><button class="btn primary" data-action="new_commitment">'+icon('plus')+'记录承诺</button></div></section><div id="page-content">'+({followups:followups,jobs:jobGrid,jobdetail:jobDetail,changes:changesPage,history,validation,about,data:dataPage,extensions:extensionsPage}[prefs.nav]||followups)()+'</div><p class="footnote">重生之我是猎头 MVP · 猎头工作记忆原型　/　数据只保存在当前浏览器。'+(MODE==='work'?'仅记录工作别名，不录入敏感资料。':'仅供虚构资料演示。')+'</p></main></div>';
if(focus==='search-input'){let el=$('#search-input');el?.focus();if(el&&el.type!=='search')el.setSelectionRange(caret,caret);}
}
function showModal(title,body,footer=''){dirty=false;returnFocus=document.activeElement;$('#modal-root').innerHTML='<div class="modal-shade"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-head"><h2 id="modal-title">'+esc(title)+'</h2><button class="close-btn" data-action="close" aria-label="关闭对话框">×</button></div><div class="modal-body">'+body+'</div>'+(footer?'<div class="modal-footer">'+footer+'</div>':'')+'</section></div>';setTimeout(()=>$('#modal-root input, #modal-root textarea, #modal-root button')?.focus(),0);}
function closeModal(force=false){if(saving&&!force){toast('正在保存，请稍候');return;}if(dirty&&!force){showDiscard();return;}dirty=false; $('#modal-root').innerHTML='';formContext=null;returnFocus?.focus();}
const options=(arr,selected)=>arr.map(([v,t])=>'<option value="'+esc(v)+'" '+(selected===v?'selected':'')+'>'+esc(t)+'</option>').join('');
function jobOptions(selected){return state.jobs.map(j=>'<option value="'+j.id+'" '+(j.id===selected?'selected':'')+'>'+esc(j.title)+(j.status==='closed'?'（已关闭）':'')+' · '+esc(userName(j.owner_id))+'</option>').join('');}
function field(label,input,small=''){return '<div class="field"><label>'+label+'</label>'+input+(small?'<small>'+small+'</small>':'')+'</div>';}
function newRecord(kind,jobId){if(!state.jobs.length){jobForm();return;}let own=state.jobs.find(j=>j.owner_id===prefs.actor&&j.status==='open'),job=jobId||(prefs.nav==='jobdetail'?prefs.jobDetail:null)||own?.id||state.jobs[0].id;formContext={kind,id:id(),snapshot:null};let isC=kind==='commitment';let fields=field('所属职位','<select name="job_id" aria-label="所属职位">'+jobOptions(job)+'</select>','只可用该职位负责人创建；已关闭职位也可记录收尾事项。');
if(isC){let sampleOpts=(MODE==='demo'?RAW.paste_cases:[]).map(p=>[p.id,p.id+' · '+p.text.slice(0,25)]);sampleOpts.push(...(MODE==='demo'?RAW.complex_format_cases:[]).map(p=>[p.id,p.id+' · 复杂合成总结']));fields+='<div class="draft-box"><h3>从已有文本粘贴 · 规则辅助</h3><textarea id="paste-text" placeholder="粘贴一项承诺。多段、多人的内容会提示手动补齐。" maxlength="6000" aria-label="待解析的沟通片段"></textarea><div class="draft-tools"><button class="btn ghost" type="button" data-action="parse">生成待确认表单</button><select id="sample-select" '+(MODE==='work'?'disabled':'')+' aria-label="载入测试文本"><option value="">'+(MODE==='demo'?'载入合成测试样例…':'演示样例仅在演示区提供')+'</option>'+options(sampleOpts,'')+'</select></div><div id="parse-warning" class="footnote">只生成草稿，不会自动保存。原始片段不会单独存入原文库。</div></div>';
fields+='<div class="field-row">'+field('沟通发生日期','<input id="source-date" name="source_date" type="date" required value="'+(MODE==='work'?C.localToday():prefs.asof)+'" aria-label="沟通发生日期">','补录旧消息时请修改；相对日期按这一天理解。')+field('内部跟进负责人','<select name="assigned_to" aria-label="内部跟进负责人">'+options(state.users.map(u=>[u.id,u.alias]),prefs.actor)+'</select>')+'</div>';
fields+='<div class="field-row">'+field('承诺人 / 对接人','<input name="person_alias" maxlength="80" placeholder="例如 HR-01；内部待办可留空" aria-label="承诺人">')+field('语气与性质','<select name="modality" id="modality" aria-label="语气与性质">'+options([['definite','明确承诺'],['conditional','有前置条件'],['tentative','暂定 / 不确定'],['request','内部请求 / 核实事项']],'definite')+'</select>')+'</div>';
fields+=field('需要跟进什么','<textarea name="action_text" required maxlength="1200" placeholder="例如：反馈 10/18 推荐的临床 PM 简历" aria-label="事项描述"></textarea>');
fields+=field('内部回看日（可选）','<input name="reminder_on" type="date" aria-label="内部回看日">','你准备哪天再核实一次？与对方承诺期限分开；仅在打开页面时提示。');
fields+='<div id="condition-fields" hidden>'+field('等待谁、哪件事？','<textarea name="condition_note" maxlength="500" placeholder="例如：等待 HR-01 反馈 10/18 推荐的 3 份简历" aria-label="等待条件"></textarea>','条件满足后仍需人工重新确认日期。')+'</div>';
fields+='<div id="date-fields"><div class="field-row">'+field('对方原话中的日期','<input name="due_raw" id="due-raw" maxlength="100" placeholder="下周三 / 周五前 / 未提供" aria-label="原始日期">')+field('确认截止日期（可留空）','<input name="due_date" id="due-date" type="date" aria-label="确认截止日期">')+'</div><button type="button" class="button-link" data-action="date_suggest">根据原话给出候选日期 →</button><div id="date-candidates" class="candidate-dates"></div><label class="check-line"><input name="due_confirmed" id="due-confirmed" type="checkbox">我已核实这个日期和“之前”是否包含当天；未勾选则进入未定日期。</label></div>';
}else{fields+=field('发生日期','<input name="happened_on" type="date" value="'+(MODE==='work'?C.localToday():prefs.asof)+'" required aria-label="变化发生日期">');fields+=field('变了什么','<textarea name="description" required maxlength="1200" placeholder="例如：从必须 MNC 背景，放宽为 Biotech 也可考虑；HR 已口头确认。" aria-label="变化描述"></textarea>');fields+=field('候选人侧同步进度','<select name="sync_status" aria-label="同步进度">'+options([['unknown','待确认'],['not_started','尚未同步'],['some_synced','已向至少一位相关候选人同步'],['not_applicable','无需同步']],'unknown')+'</select>','“至少一位”不代表所有受影响候选人均已同步。');}
fields+=field('来源备注','<input name="source_note" maxlength="300" placeholder="例如：10/19 与 HR-01 电话（仅填必要的别名与事项）" aria-label="来源备注">');showModal(isC?'记录一项承诺':'记录需求变化','<div class="form-callout">'+(MODE==='work'?'仅填写必要的工作别名与事项。':'当前为合成资料演示。')+' 确认后才保存到此浏览器；不会发消息。</div><div id="form-error"></div><form id="record-form">'+fields+'</form>','<button class="btn secondary" data-action="close">取消</button><button class="btn primary" form="record-form" type="submit">确认并保存</button>');}
function setFormError(msg){let e=$('#form-error');if(e)e.innerHTML='<div class="form-error" role="alert">'+esc(msg)+'</div>';else toast(msg,true);}
function conditionToggle(){let cond=$('#modality')?.value==='conditional';$('#condition-fields').hidden=!cond;$('#date-fields').hidden=cond;if(cond){$('#due-date').value='';$('#due-confirmed').checked=false;}}
function suggestDate(){let raw=$('#due-raw').value,source=$('#source-date').value,res=C.dateDraft(raw,source);$('#date-candidates').innerHTML=res.dates.map(d=>'<button type="button" data-action="pick_date" data-value="'+d+'">'+d+'（待确认）</button>').join('')+'<small>'+esc(res.warning)+(res.range?'：'+res.range.join(' 至 '):'')+'</small>';}
function parse(){dirty=true;let f=$('#record-form'),p=C.parseDraft($('#paste-text').value,$('#source-date').value);f.elements.person_alias.value=p.person_alias;f.elements.action_text.value=p.action_text;f.elements.due_raw.value=p.due_raw;f.elements.modality.value=p.modality;f.elements.condition_note.value=p.condition_note;$('#due-date').value='';$('#due-confirmed').checked=false;conditionToggle();$('#parse-warning').textContent=p.warning;if(!p.fallback&&p.modality!=='conditional')suggestDate();else $('#date-candidates').innerHTML='';}
function followupTimeline(cid){const notes=C.commitmentNotes(state,cid);return '<section class="followup-timeline"><h3>跟进结果 · '+notes.length+' 条</h3><p class="footnote">整条改期链的记录一起展示。原回看安排仅是保存时的历史快照，当前安排以事项详情为准。</p>'+(notes.length?notes.map(n=>{const c=state.commitments.find(c=>c.id===n.commitment_id),can=n.created_by===prefs.actor&&C.canEdit(state,c,prefs.actor);return '<article class="note-block"><strong>'+esc(n.occurred_on)+'</strong> · '+esc(userName(n.created_by))+(n.commitment_id!==cid?' <span class="tag">来自改期链其他条目</span>':'')+'<p class="followup-text">'+esc(n.note)+'</p><small>记录时别名：'+esc(n.person_alias||'内部事项')+' · '+esc(n.review_mode==='set'?'当时安排回看：'+n.review_date:n.review_mode==='clear'?'当时清除回看日':'当时保留原回看安排')+(n.updated_at!==n.created_at?' · 已修正':'')+'</small>'+(can?'<div><button class="button-link" data-action="edit_followup" data-id="'+esc(n.id)+'">修正结果</button> <button class="button-link" data-action="delete_followup" data-id="'+esc(n.id)+'">删除这条结果</button></div>':'')+'</article>';}).join(''):'<p>尚未记录跟进结果。</p>')+'</section>';}
function followupModal(cid,nid){const c=state.commitments.find(c=>c.id===cid),n=(state.followups||[]).find(n=>n.id===nid);if(!c)return;formContext={kind:n?'edit_followup':'record_followup',id:n?n.id:id(),snapshot:C.clone(n||c),commitment_id:c.id};let fields=field('跟进发生日','<input name="occurred_on" type="date" required max="'+C.localToday()+'" value="'+esc(n?n.occurred_on:C.localToday())+'" aria-label="跟进发生日">')+field('这次跟进得到什么结果','<textarea name="note" required maxlength="800" rows="5" aria-label="跟进结果" placeholder="只记录实际发生的沟通和必要的别名">'+esc(n?.note||'')+'</textarea>');if(!n&&c.status==='pending')fields+=field('下次内部回看安排','<select name="review_mode" id="followup-review-mode" aria-label="下次内部回看安排"><option value="preserve">保留当前安排</option><option value="set">设置新的内部回看日</option><option value="clear">清除当前回看日</option></select>')+field('下次内部回看日','<input name="reminder_on" type="date" aria-label="下次内部回看日" disabled>','当前：'+esc(c.reminder_on||'未设置')+'。关闭页面后不主动通知。');showModal(n?'修正跟进结果':'记录跟进结果','<p class="detail-title">'+esc(c.action_text)+'</p><div class="form-callout">'+(n?'只修正结果与发生日，原回看安排的历史快照不变。':'记录结果不会自动完成事项，也不会更改对方承诺的截止日；不会发消息。')+'</div><div id="form-error"></div><form id="followup-form">'+fields+'</form>','<button class="btn secondary" data-action="close">取消</button><button class="btn primary" form="followup-form" type="submit">确认并保存</button>');}
function detail(cid){let c=state.commitments.find(x=>x.id===cid);if(!c)return;let j=jobFor(c),can=C.canEdit(state,c,prefs.actor),row=(a,b)=>'<dt>'+a+'</dt><dd>'+esc(b||'未提供')+'</dd>';formContext={kind:'detail',snapshot:C.clone(c)};let actions=can&&c.status==='pending'?'<button class="btn secondary" data-action="reminder" data-id="'+c.id+'">设置内部回看日</button><button class="btn secondary" data-action="edit_commitment" data-id="'+c.id+'">修改内容</button><button class="btn primary" data-action="complete" data-id="'+c.id+'">标记完成</button>'+(c.condition_state==='waiting'?'<button class="btn secondary" data-action="release" data-id="'+c.id+'">核实并解除等待</button>':!c.due_confirmed?'<button class="btn secondary" data-action="confirm_date" data-id="'+c.id+'">确认日期</button>':'<button class="btn secondary" data-action="reschedule" data-id="'+c.id+'">改期</button>')+'<button class="btn ghost" data-action="cancel" data-id="'+c.id+'">取消事项</button>':'';showModal('事项详情','<div class="item-top">'+viewTag(c)+(j.status==='closed'?'<span class="tag">职位已关闭</span>':'')+'</div><div class="detail-title">'+esc(c.action_text)+'</div><dl class="detail-dl">'+row('所属职位',j.title)+row('承诺人',c.person_alias||'无 · 内部待办')+row('跟进负责人',userName(c.assigned_to))+row('沟通发生日',c.source_date)+row('日期原话',c.due_raw)+row('已确认期限',c.due_confirmed?c.due_date:'尚未确认')+row('内部回看日',c.reminder_on)+row('等待什么',c.condition_note)+row('来源备注',c.source_note)+(c.rescheduled_from?row('改期历史',c.rescheduled_from):'')+row('记录编号',c.id)+'</dl>'+(!can?'<p class="footnote">当前模拟身份仅可查看。切换为跟进负责人或创建者可操作。</p>':'')+followupTimeline(c.id)+(c.status==='rescheduled'?'<p><button class="button-link" data-action="detail" data-id="'+esc(state.commitments.find(x=>C.chainIds(state,c.id).includes(x.id)&&x.status!=='rescheduled')?.id||c.id)+'">打开改期链当前条目 →</button></p>':'')+'<div class="detail-actions">'+(can&&c.status!=='rescheduled'?'<button class="btn primary" data-action="record_followup" data-id="'+c.id+'">记录跟进结果</button>':'')+actions+(can?'<button class="btn danger" data-action="delete" data-id="'+c.id+'">删除'+(c.rescheduled_from||state.commitments.some(x=>x.rescheduled_from===c.id)?'整条承诺链':'记录')+'</button>':'')+'</div>','<button class="btn secondary" data-action="close">关闭</button>');recordView(c.id);}
function recordView(){/* Read-only viewing must not overwrite a mutation recovery point. */}
function dateModal(type,cid){let c=state.commitments.find(x=>x.id===cid);if(!c)return;formContext={kind:'date',type,snapshot:C.clone(c),child_id:id()};let title={reschedule:'确认改期',confirm_date:'确认具体截止日期',release:'核实条件并重新确认日期'}[type];showModal(title,'<p class="detail-title">'+esc(c.action_text)+'</p>'+(type==='release'?'<div class="form-callout">等待条件：'+esc(c.condition_note)+'<br>请先核实条件已满足，再重新确认截止日；不会自动平移原日期。</div>':'')+'<div id="form-error"></div><form id="date-form">'+field('新的明确截止日期','<input name="due_date" type="date" required value="'+(c.due_date||prefs.asof)+'" aria-label="新的截止日期">')+'<label class="check-line"><input name="confirmed" type="checkbox" required>我已核实'+(type==='release'?'条件已满足，并重新确认了':'')+'这个日期</label></form>','<button class="btn secondary" data-action="close">取消</button><button class="btn primary" form="date-form" type="submit">确认</button>');}
function changeDetail(cid){let c=state.changes.find(x=>x.id===cid);if(!c)return;let can=C.canEdit(state,c,prefs.actor);formContext={kind:'change_detail',snapshot:C.clone(c)};showModal('变化详情','<div class="detail-title">'+esc(c.description)+'</div><dl class="detail-dl"><dt>所属职位</dt><dd>'+esc(jobFor(c).title)+'</dd><dt>发生日期</dt><dd>'+esc(c.happened_on)+'</dd><dt>来源</dt><dd>'+esc(c.source_note)+'</dd><dt>状态</dt><dd>'+esc(c.status)+'</dd>'+(c.status_note?'<dt>说明</dt><dd>'+esc(c.status_note)+'</dd>':'')+'</dl><div class="note-block">顾问需要判断这条变化是否影响现有承诺。系统不会自动取消或改期。</div>'+(can?'<div class="field"><label>更新同步进度</label><select id="change-sync">'+options([['unknown','待确认'],['not_started','尚未同步'],['some_synced','已向至少一位同步'],['not_applicable','无需同步']],c.sync_status)+'</select></div><div class="detail-actions"><button class="btn secondary" data-action="edit_change" data-id="'+c.id+'">修改内容</button><button class="btn primary" data-action="save_sync" data-id="'+c.id+'">保存同步进度</button>'+(c.status==='active'?'<button class="btn ghost" data-action="void_change" data-id="'+c.id+'">标记作废</button>':'')+'<button class="btn danger" data-action="delete_change" data-id="'+c.id+'">删除记录</button></div>':'<p class="footnote">当前身份仅可查看。</p>'),'<button class="btn secondary" data-action="close">关闭</button>');}
function confirmModal(title,body,action,recordId){showModal(title,'<p style="font-size:12px;line-height:1.9;color:#7e8c72">'+esc(body)+'</p>','<button class="btn secondary" data-action="close">返回</button><button class="btn danger" data-action="'+action+'" '+(recordId?'data-id="'+recordId+'"':'')+'>确认</button>');}
function download(name,content,type='text/plain'){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
function exportText(){let lines=['重生之我是猎头 MVP｜'+(MODE==='work'?'个人工作记录':'合成演示记录'),'导出日期：'+C.localToday(),'评估日期：'+prefs.asof,MODE==='work'?'内部工作记忆，非客户报告；文本文件不能用于恢复。':'仅供虚构资料演示，不是真实顾问访谈或使用效果。',''];state.jobs.forEach(j=>{lines.push('\n【'+j.title+'】'+(j.status==='closed'?'（已关闭）':''));state.changes.filter(c=>c.job_id===j.id).forEach(c=>lines.push('变化：'+c.description+'｜'+c.happened_on+'｜'+c.source_note));state.commitments.filter(c=>c.job_id===j.id).forEach(c=>lines.push('事项：'+c.action_text+'｜对接：'+(c.person_alias||'内部事项')+'｜负责人：'+userName(c.assigned_to)+'｜'+viewLabels[C.view(c,prefs.asof)]+'｜'+(c.due_confirmed?c.due_date:'日期未确认')+(c.reminder_on?'｜内部回看：'+c.reminder_on:'')+(c.condition_note?'｜等待：'+c.condition_note:'')));state.followups.filter(n=>n.job_id===j.id).forEach(n=>lines.push('跟进结果：'+n.occurred_on+'｜事项编号：'+n.commitment_id+'｜记录时别名：'+(n.person_alias||'内部事项')+'｜'+n.note+'｜原回看安排：'+(n.review_mode==='set'?n.review_date:n.review_mode==='clear'?'清除':'保留')));});download('重生之我是猎头 MVP-'+(MODE==='work'?'工作':'模拟')+'记录.txt',C.redact(lines.join('\n')));toast('已请求下载阅读版文本；恢复数据请使用完整备份');}
function showDiscard(){
 if($('#discard-warning'))return;
 const body=$('#modal-root .modal-body');
 if(body)body.insertAdjacentHTML('afterbegin','<div id="discard-warning" class="notice" role="alert">有未保存的修改。<button class="btn secondary" data-action="keep_editing">继续编辑</button><button class="btn danger" data-action="discard_edits">放弃修改并关闭</button></div>');
}
function jobForm(jid){
 const j=state.jobs.find(j=>j.id===jid);
 formContext={kind:'job',id:j?.id||id(),snapshot:j?C.clone(j):null};
 showModal(j?'修改职位':'新建职位','<div id="form-error"></div><form id="job-form">'+field('职位名称','<input name="title" required maxlength="160" aria-label="职位名称" value="'+esc(j?.title||'')+'">')+field('客户别名','<input name="client_alias" required maxlength="100" aria-label="客户别名" value="'+esc(j?.client_alias||'')+'">')+'<p class="footnote">请只填写必要的职位名称与客户别名。当前负责人：'+esc(userName(prefs.actor))+'。</p></form>','<button class="btn secondary" data-action="close">取消</button><button class="btn primary" form="job-form" type="submit">确认并保存</button>');
}
function editRecord(type,cid){
 const c=(type==='edit_commitment'?state.commitments:state.changes).find(c=>c.id===cid);
 if(!c)return;formContext={kind:type,snapshot:C.clone(c)};
 let fields='';
 if(type==='edit_commitment'){
  fields+=field('承诺人 / 对接人','<input name="person_alias" maxlength="80" aria-label="承诺人" value="'+esc(c.person_alias||'')+'">');
  fields+=field('需要跟进什么','<textarea name="action_text" required maxlength="1200" aria-label="事项描述">'+esc(c.action_text)+'</textarea>');
  fields+=field('沟通发生日期','<input name="source_date" type="date" required aria-label="沟通发生日期" value="'+esc(c.source_date)+'">');
  fields+=field('跟进负责人','<select name="assigned_to" aria-label="内部跟进负责人">'+options(state.users.map(u=>[u.id,u.alias]),c.assigned_to)+'</select>');
  if(c.condition_state==='waiting')fields+=field('等待谁、哪件事','<textarea name="condition_note" required maxlength="500" aria-label="等待条件">'+esc(c.condition_note)+'</textarea>');
  fields+='<p class="footnote">此处只修改记录内容。调整期限请用“改期”或“确认日期”，解除条件请用“核实并解除等待”，保留各自的明确操作。</p>';
 }else{
  fields+=field('变化描述','<textarea name="description" required maxlength="1200" aria-label="变化描述">'+esc(c.description)+'</textarea>');
  fields+=field('发生日期','<input name="happened_on" type="date" required value="'+esc(c.happened_on)+'">');
 }
 fields+=field('来源备注','<input name="source_note" maxlength="300" aria-label="来源备注" value="'+esc(c.source_note||'')+'">');
 showModal('修改记录内容','<div id="form-error"></div><form id="edit-form">'+fields+'</form>','<button class="btn secondary" data-action="close">取消</button><button class="btn primary" form="edit-form" type="submit">确认并保存</button>');
}
async function importFile(file){
 if(!file)return;if(file.size>D.MAX_BYTES)throw Error('备份不能超过 10 MB');
 const result=await D.readBackup(await file.text());
 previewRestore(result.state,'备份时间：'+result.created_at);
}
function previewRestore(candidate,source){
 if(candidate.dataset_kind!==MODE)throw Error('备份属于'+(candidate.dataset_kind==='work'?'工作区':'演示区')+'，请先切换到对应区域');
 const n=D.summary(candidate);
 formContext={kind:'restore',candidate,expectedRaw:store.raw(),mode:MODE};
 showModal('预览恢复内容','<div class="form-callout">'+esc(source)+'<br>职位 '+n.jobs+' 个；事项 '+n.commitments+' 条（待跟进 '+n.active+' 条）；变化 '+n.changes+' 条；跟进结果 '+candidate.followups.length+' 条。</div><p>确认后替换当前'+(MODE==='work'?'工作区':'演示区')+'，不合并记录。建议先下载当前完整备份。</p><p>恢复成功后保留替换前的有效数据作为一个恢复点。</p>','<button class="btn secondary" data-action="close">取消</button><button class="btn danger" data-action="restore_confirm">确认替换并恢复</button>');
}
function reminderModal(cid){const c=state.commitments.find(x=>x.id===cid);if(!c)return;formContext={kind:'reminder',snapshot:C.clone(c)};showModal('设置内部回看日','<p>'+esc(c.action_text)+'</p><div id="form-error"></div><form id="reminder-form">'+field('内部回看日','<input name="reminder_on" type="date" aria-label="内部回看日" value="'+esc(c.reminder_on||'')+'">','留空可清除。只安排自己的回看，不改变对方承诺、等待状态或截止日。页面关闭后不主动通知。')+'</form>','<button class="btn secondary" data-action="close">取消</button><button class="btn primary" type="submit" form="reminder-form">确认并保存</button>');}
async function extraAction(action,el){
 if(action==='record_followup'){followupModal(el.dataset.id);return true;}
 if(action==='edit_followup'){const n=state.followups.find(n=>n.id===el.dataset.id);if(n)followupModal(n.commitment_id,n.id);return true;}
 if(action==='delete_followup'){const n=state.followups.find(n=>n.id===el.dataset.id);if(!n)return true;formContext={kind:'delete_followup',snapshot:C.clone(n)};confirmModal('删除这条跟进结果','事项本身和当前回看安排不会删除；可在数据管理中恢复上一次保存。','delete_followup_confirm',n.id);return true;}
 if(action==='delete_followup_confirm'){const n=formContext?.kind==='delete_followup'&&formContext.snapshot;if(!n)throw Error('删除预览已失效');await mutate({type:'delete_followup',id:n.id,expected_updated_at:n.updated_at});detail(n.commitment_id);render();toast('已删除跟进结果');return true;}
 if(action==='reminder'){reminderModal(el.dataset.id);return true;}
 if(action==='new_job'||action==='edit_job'){jobForm(el.dataset.id);return true;}
 if(action==='edit_commitment'||action==='edit_change'){editRecord(action,el.dataset.id);return true;}
 if(action==='keep_editing'){$('#discard-warning')?.remove();return true;}
 if(action==='discard_edits'){closeModal(true);return true;}
 if(action==='switch_mode'){
  if(dirty){showDiscard();return true;}
  MODE=MODE==='work'?'demo':'work';savedPrefs={};loadWorkspace();prefs.nav='followups';prefs.job='all';prefs.owner='all';prefs.query='';prefs.filter='active';prefs.reviewJob=null;prefs.reviewPerson=null;savePrefs();render();return true;
 }
 if(action==='backup'){
  if(!storageOK&&!stateTrusted)throw Error('当前数据不可验证，请先导出存储原文或恢复有效备份');
  const mode=MODE,target=store,trusted=stateTrusted;let memoryOnly=!storageOK;const snapshot=C.clone(state);const make=()=>{let current;if(!memoryOnly){try{current=target.read();}catch(e){if(!trusted)throw e;memoryOnly=true;}}if(!current){if(!trusted)throw Error('当前没有可验证的有效副本');current=snapshot;memoryOnly=true;}return D.backup(current,new Date().toISOString());};const saved=await (navigator.locks?navigator.locks.request(LOCK,make):make());
  download('猎头工作台-'+mode+'-完整备份-'+C.localToday()+'.json',JSON.stringify(saved,null,2),'application/json');toast(memoryOnly?'已请求下载页面保留副本，可能不含其他页面的后续修改；请确认下载完成':'已请求下载完整备份，请确认浏览器下载完成');return true;
 }
 if(action==='raw_export'){download('猎头工作台-'+MODE+'-存储原文.txt',store.raw()||'当前没有存储内容');return true;}
 if(action==='import_pick'){$('#backup-input').value='';$('#backup-input').click();return true;}
 if(action==='previous_preview'){previewRestore(store.previous(),'上一次成功修改前的恢复点');return true;}
 if(action==='restore_confirm'){
  const ctx=formContext;if(ctx?.kind!=='restore'||ctx.mode!==MODE)throw Error('恢复预览已失效，请重新选择备份');
  const run=()=>{const restored=D.validate(ctx.candidate),now=new Date().toISOString();
   // Refresh conflict tokens so forms opened before a restore cannot write stale data.
   for(const row of [...restored.jobs,...restored.commitments,...restored.changes,...restored.followups])row.updated_at=new Date(Math.max(Date.parse(now),Date.parse(row.updated_at)+1)).toISOString();
   state=store.write(restored,ctx.expectedRaw);stateTrusted=true;storageOK=true;storageError='';};
  if(navigator.locks)await navigator.locks.request(LOCK,run);else run();
  prefs.actor=state.users.some(u=>u.id===prefs.actor)?prefs.actor:state.users[0].id;prefs.job='all';prefs.owner='all';prefs.query='';prefs.filter='active';savePrefs();closeModal(true);render();toast('恢复完成；已保留替换前的有效恢复点');return true;
 }
 return false;
}

async function doAction(action,el){if(saving){toast('正在保存，请稍候');return;}let cid=el?.dataset.id,value=el?.dataset.value;
if(action==='reminder_list'){prefs.nav='extensions';prefs.module='reminder-queue';render();return;}
if(action==='nav'){prefs.nav=value;prefs.query='';prefs.job='all';prefs.filter='active';render();return;}
if(action==='job'){prefs.nav='jobdetail';prefs.jobDetail=cid;prefs.query='';render();return;}
if(action==='filter'){prefs.filter=value;render();return;}
if(action==='today'){prefs.clockMode='live';prefs.asof=C.localToday();savePrefs();render();return;}
if(action==='new_commitment'||action==='new_change'){newRecord(action==='new_commitment'?'commitment':'change',el.dataset.job);return;}
if(action==='close'){closeModal();return;}
if(action==='detail'){detail(cid);return;}
if(action==='change_detail'){changeDetail(cid);return;}
if(action==='parse'){parse();return;}
if(action==='date_suggest'){suggestDate();return;}
if(action==='pick_date'){dirty=true;$('#due-date').value=value;$('#due-confirmed').checked=false;toast('已选择候选日期，请核实后勾选确认');return;}
if(['release','reschedule','confirm_date'].includes(action)){dateModal(action,cid);return;}
if(action==='complete'||action==='cancel'){let c=state.commitments.find(x=>x.id===cid);formContext={kind:action,snapshot:C.clone(c)};confirmModal(action==='complete'?'确认标记完成':'确认取消事项',c.action_text,action==='complete'?'confirm_complete':'confirm_cancel',cid);return;}
if(action==='confirm_complete'||action==='confirm_cancel'){action=action==='confirm_complete'?'complete':'cancel';let c=formContext?.snapshot?.id===cid?formContext.snapshot:state.commitments.find(x=>x.id===cid);await mutate({type:action,id:cid,expected_updated_at:c.updated_at});closeModal(true);render();toast(action==='complete'?'已记录完成':'已取消；历史仍保留');return;}
if(action==='save_sync'){let c=formContext.snapshot;await mutate({type:'change_sync',id:cid,value:$('#change-sync').value,expected_updated_at:c.updated_at});closeModal(true);render();toast('同步进度已保存');return;}
if(action==='void_change'){let c=formContext.snapshot;formContext={kind:'void',snapshot:C.clone(c)};showModal('标记变化作废','<div id="form-error"></div><form id="void-form">'+field('作废说明','<textarea name="note" required maxlength="300" placeholder="简要说明这条信息为什么作废" aria-label="作废说明"></textarea>')+'</form>','<button class="btn secondary" data-action="close">返回</button><button class="btn primary" type="submit" form="void-form">确认作废</button>');return;}
if(action==='delete'||action==='delete_change'){let c=action==='delete'?state.commitments.find(x=>x.id===cid):state.changes.find(x=>x.id===cid);formContext={kind:action,snapshot:C.clone(c)};confirmModal('删除本机记录','删除会移除记录内容及所属跟进结果，改期事项会删除整条链。请先下载完整备份；上一次保存恢复点会在下一次修改时被替换。',action==='delete'?'confirm_delete':'confirm_delete_change',cid);return;}
if(action==='confirm_delete'||action==='confirm_delete_change'){let c=formContext.snapshot;await mutate({type:action==='confirm_delete'?'delete_chain':'change_delete',id:cid,expected_updated_at:c.updated_at});closeModal(true);render();toast('记录内容已从本机删除');return;}
if(action==='job_toggle'){let j=state.jobs.find(x=>x.id===cid);formContext={kind:'job_toggle',snapshot:C.clone(j)};confirmModal(j.status==='closed'?'重新打开职位':'关闭职位','职位状态变化不会自动关闭其未完成事项。','confirm_job_toggle',cid);return;}
if(action==='confirm_job_toggle'){let j=formContext.snapshot;await mutate({type:'job_status',id:cid,status:j.status==='closed'?'open':'closed',expected_updated_at:j.updated_at});closeModal(true);render();toast('职位状态已更新；待跟进事项保留');return;}
if(action==='export'){exportText();return;}
if(await extraAction(action,el))return;
if(action==='export_logs'){download('重生之我是猎头 MVP-本机演示操作记录.json',JSON.stringify({synthetic_workspace:MODE==='demo',note:'本机操作记录，不含企业审计保证；不记录只读回看',logs:state.logs},null,2),'application/json');return;}
if(action==='export_report'){download('重生之我是猎头 MVP-浏览器检查结果.json',JSON.stringify({as_of:prefs.asof,synthetic:MODE==='demo',workspace:MODE,checks:checks(),counts:Object.fromEntries(C.VIEWS.map(v=>[v,C.partitions(state,prefs.asof)[v].length])),not_tested:['真实用户需求','服务端多租户','真实CTS或Voice','真实解析覆盖率']},null,2),'application/json');return;}
if(action==='reset'){confirmModal('恢复初始模拟数据','此操作会清除你在本浏览器新增的演示记录和本机操作日志，恢复 32 条合成承诺。','confirm_reset');return;}
if(action==='confirm_reset'){if(MODE!=='demo')throw Error('工作区不能重置为模拟数据');await withWrite(()=>{state=store.write(D.validate(C.seed(RAW)),store.raw());});prefs.clockMode='fixed';prefs.asof='2026-10-19';savePrefs();closeModal(true);render();toast('已恢复初始合成数据');return;}
if(action==='show_formats'){let text=RAW.complex_format_cases.map(p=>p.id+'\n'+p.text+'\n预期：'+JSON.stringify(p.expected_invariants)).join('\n\n');showModal('复杂格式样例 · 全部为合成','<div class="form-callout">用于测试规则能否安全回退；不代表真实 Voice/CTS 格式或已验证覆盖率。</div><pre style="white-space:pre-wrap;font-size:11px;line-height:1.9;color:#7b896e">'+esc(text)+'</pre>','<button class="btn secondary" data-action="close">关闭</button>');return;}
}
document.addEventListener('click',e=>{let el=e.target.closest('[data-action]');if(!el)return;Promise.resolve(doAction(el.dataset.action,el)).catch(err=>setFormError(err.message));});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#modal-root').children.length){closeModal();return;}if((e.key==='Enter'||e.key===' ')&&e.target.matches('p[data-action]')){e.preventDefault();e.target.click();}if(e.key==='Tab'&&$('#modal-root').children.length){let all=Array.from($('#modal-root').querySelectorAll('button,input,select,textarea')).filter(x=>!x.disabled&&x.getClientRects().length);let first=all[0],last=all[all.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
document.addEventListener('input',e=>{if(e.target.closest('#modal-root form'))dirty=true;if(e.target.id==='search-input'){prefs.query=e.target.value;render();}if(['due-date','due-raw','source-date'].includes(e.target.id)&&$('#due-confirmed'))$('#due-confirmed').checked=false;});
document.addEventListener('change',e=>{let t=e.target;if(t.closest('#modal-root form'))dirty=true;if(t.id==='module-select'){prefs.module=t.value;render();}if(t.id==='review-person'){prefs.reviewPerson=t.value==='*'?null:JSON.parse(t.value);render();}if(t.id==='review-job'){prefs.reviewJob=t.value;prefs.reviewPerson=null;render();}if(t.id==='backup-input'){importFile(t.files?.[0]).catch(e=>toast(e.message,true));}if(t.id==='actor-select'){prefs.actor=t.value;savePrefs();render();}if(t.id==='asof-date'){if(C.validDate(t.value)){prefs.clockMode='fixed';prefs.asof=t.value;savePrefs();render();}}if(t.id==='owner-filter'){prefs.owner=t.value;render();}if(t.id==='job-filter'){prefs.job=t.value;render();}if(t.id==='show-closed'){prefs.showClosed=t.checked;render();}if(t.id==='modality')conditionToggle();if(t.id==='sample-select'&&t.value){let p=[...RAW.paste_cases,...RAW.complex_format_cases].find(p=>p.id===t.value);$('#paste-text').value=p.text;$('#source-date').value=p.source_date;$('#record-form').elements.job_id.value=p.job_id;$('#due-confirmed').checked=false;toast('已载入合成文本；可点击生成待确认表单');}});
document.addEventListener('change',e=>{if(e.target.id==='followup-review-mode'){const date=document.querySelector('#followup-form [name="reminder_on"]');date.disabled=e.target.value!=='set';date.required=!date.disabled;if(date.disabled)date.value='';}});
document.addEventListener('submit',async e=>{if(!['record-form','date-form','void-form','job-form','edit-form','reminder-form','followup-form'].includes(e.target.id))return;e.preventDefault();const ctx=formContext,form=e.target,button=document.querySelector('[form="'+form.id+'"][type="submit"]');if(button.disabled)return;button.disabled=true;saving=true;try{let fd=new FormData(form),p=Object.fromEntries(fd.entries());if(form.id==='followup-form'){await mutate({type:ctx.kind,id:ctx.id,commitment_id:ctx.commitment_id,expected_updated_at:ctx.snapshot.updated_at,payload:p});}else if(form.id==='reminder-form'){await mutate({type:'set_reminder',id:ctx.snapshot.id,expected_updated_at:ctx.snapshot.updated_at,reminder_on:p.reminder_on||null});}else if(form.id==='job-form'){await mutate({type:ctx.snapshot?'edit_job':'create_job',id:ctx.id,payload:p,...(ctx.snapshot?{expected_updated_at:ctx.snapshot.updated_at}:{})});}else if(form.id==='edit-form'){await mutate({type:ctx.kind,id:ctx.snapshot.id,payload:p,expected_updated_at:ctx.snapshot.updated_at});}else if(form.id==='record-form'){p.due_confirmed=fd.has('due_confirmed');p.condition_state=p.modality==='conditional'?'waiting':'not_applicable';await mutate({type:ctx.kind==='commitment'?'create_commitment':'create_change',id:ctx.id,payload:p});}else if(form.id==='date-form'){await mutate({type:ctx.type,id:ctx.snapshot.id,expected_updated_at:ctx.snapshot.updated_at,due_date:p.due_date,due_confirmed:fd.has('confirmed'),child_id:ctx.child_id});}else await mutate({type:'change_void',id:ctx.snapshot.id,expected_updated_at:ctx.snapshot.updated_at,note:p.note});closeModal(true);render();toast('已保存到当前浏览器');}catch(err){setFormError(err.message);button.disabled=false;}finally{saving=false;}});
window.addEventListener('storage',e=>{if(e.key===KEY||e.key===null){if(!storageOK){toast('检测到其他页面改动；请先备份页面保留副本，再重新打开读取新数据',true);return;}try{if(e.newValue===null)throw Error('当前存储已被外部清除，原页面内容未自动覆盖');state=read();stateTrusted=true;storageOK=true;storageError='';render();toast('另一标签页已更新；未保存表单会在提交时检查冲突');}catch(err){storageOK=false;storageError=err.message;render();toast('数据发生异常，已停止写入；请到数据管理排查',true);}}});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
setInterval(()=>{if(prefs.clockMode==='live'&&prefs.asof!==C.localToday())render();},30000);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&prefs.clockMode==='live')render();});
render();
})();
